            actHint.style.cssText = "font-family:'Trebuchet MS',serif;font-size:11px;color:#9a6878;line-height:1.4;margin-bottom:4px;";
            actHint.textContent = "Sends a visible room emote for each action.";
            actPanel.appendChild(actHint);
            const ACT_DEFS = [
                ["👋", "Spank", "Spank", "ItemButt"],
                ["🖐", "Pat", "Pat", "ItemHead"],
                ["💋", "Kiss", "Kiss", "ItemMouth"],
                ["🦷", "Bite", "Bite", "ItemNeck"],
                ["✋", "Slap", "Slap", "ItemHead"],
                ["🖐", "Caress", "Caress", "ItemArms"],
                ["👊", "Bap", "Bap", "ItemHead"],
                ["🫦", "Lick", "Lick", "ItemHead"],
            ];
            const actGrid = document.createElement("div");
            actGrid.style.cssText = "display:grid;grid-template-columns:repeat(4,1fr);gap:4px;";
            const actStatus = document.createElement("div");
            actStatus.style.cssText = "font-family:'Trebuchet MS',serif;font-size:11px;color:#79a885;min-height:13px;margin-top:2px;";
            for (const [emoji, label, actName, zone] of ACT_DEFS) {
                const btn = document.createElement("button");
                btn.style.cssText = "font-family:'Trebuchet MS',serif;font-size:11px;font-weight:bold;padding:7px 2px;border-radius:6px;border:1px solid #5a3a50;background:#2a1020;color:#cf6f98;cursor:pointer;transition:background 0.12s,border-color 0.12s;text-align:center;";
                btn.textContent = `${emoji} ${label}`;
                btn.title = `${actName} (${zone})`;
                btn.addEventListener("mouseenter", () => { btn.style.background = "#4a1830"; btn.style.borderColor = "#cf6f98"; });
                btn.addEventListener("mouseleave", () => { btn.style.background = "#2a1020"; btn.style.borderColor = "#5a3a50"; });
                btn.addEventListener("click", () => {
                    const id = parseInt(qtSel.value, 10);
                    if (!id) {
                        actStatus.textContent = "Pick a Focus Target first.";
                        window.setTimeout(() => { actStatus.textContent = ""; }, 2500);
                        return;
                    }
                    const ok = performActivityOnTarget(id, actName, zone);
                    actStatus.textContent = ok ? `✓ ${label} → done.` : `⚠ ${label} failed (not in room?).`;
                    window.setTimeout(() => { actStatus.textContent = ""; }, 2500);
                });
                actGrid.appendChild(btn);
            }
            actPanel.appendChild(actGrid);
            actPanel.appendChild(actStatus);
            // ── 🧎 Poses ──────────────────────────────────────────────────────────
            const { panel: posePanel } = makeDomAccordion("🧎", "POSES", actionsCard);
            const POSE_DEFS = [
                ["🚶", "Stand", [], ""],
                ["🧎", "Kneel", ["Kneel"], "into a kneeling position"],
                ["🐈", "All Fours", ["AllFours"], "onto all fours"],
                ["🙌", "Hands Up", ["OverTheHead"], "into a hands-up pose"],
                ["🫸", "Spread", ["KneelingSpread"], "into a kneeling spread"],
                ["🤸", "Kneel+Up", ["Kneel", "OverTheHead"], "into a kneeling position with arms raised"],
                ["🙏", "Tight Back", ["BackElbowTouch"], "arms pulled tight behind the back"],
                ["🧎", "Kneel+Tight", ["Kneel", "BackElbowTouch"], "into a kneeling position with arms tight behind the back"],
            ];
            const poseGrid = document.createElement("div");
            poseGrid.style.cssText = "display:grid;grid-template-columns:repeat(3,1fr);gap:4px;";
            const poseStatus = document.createElement("div");
            poseStatus.style.cssText = "font-family:'Trebuchet MS',serif;font-size:11px;color:#79a885;min-height:13px;margin-top:2px;";
            for (const [emoji, label, poses, actionDesc] of POSE_DEFS) {
                const btn = document.createElement("button");
                btn.style.cssText = "font-family:'Trebuchet MS',serif;font-size:11px;font-weight:bold;padding:7px 2px;border-radius:6px;border:1px solid #5a3a50;background:#2a1020;color:#cf6f98;cursor:pointer;transition:background 0.12s,border-color 0.12s;text-align:center;";
                btn.textContent = `${emoji} ${label}`;
                btn.title = poses.length ? poses.join("+") : "Clear all poses";
                btn.addEventListener("mouseenter", () => { btn.style.background = "#4a1830"; btn.style.borderColor = "#cf6f98"; });
                btn.addEventListener("mouseleave", () => { btn.style.background = "#2a1020"; btn.style.borderColor = "#5a3a50"; });
                btn.addEventListener("click", () => {
                    const id = parseInt(qtSel.value, 10);
                    if (!id) {
                        poseStatus.textContent = "Pick a Focus Target first.";
                        window.setTimeout(() => { poseStatus.textContent = ""; }, 2500);
                        return;
                    }
                    setTargetPoses(id, poses, actionDesc || undefined);
                    poseStatus.textContent = `✓ ${label} applied.`;
                    window.setTimeout(() => { poseStatus.textContent = ""; }, 2000);
                });
                poseGrid.appendChild(btn);
            }
            posePanel.appendChild(poseGrid);
            posePanel.appendChild(poseStatus);
            // ── 🎮 Toy Control ────────────────────────────────────────────────────
            const { panel: toyPanel, hdr: toyHdr, isOpen: isToyOpen } = makeDomAccordion("🎮", "TOY CONTROL", actionsCard);
            const TOY_MODES = [
                ["⏹", "Off", "#2a1020", "Off"],
                ["🔅", "Low", "#1a2030", "Low"],
                ["🔆", "Medium", "#1a3020", "Medium"],
                ["⚡", "High", "#302010", "High"],
                ["🔥", "Max", "#3a1010", "Maximum"],
                ["😤", "Tease", "#1a2a30", "Tease"],
                ["🎲", "Random", "#2a1a30", "Random"],
                ["📈", "Escalate", "#3a0e18", "Escalate"],
                ["🚫", "Deny", "#301828", "Deny"],
                ["🌊", "Edge", "#182830", "Edge"],
            ];
            const toyHint = document.createElement("div");
            toyHint.style.cssText = "font-family:'Trebuchet MS',serif;font-size:11px;color:#9a6878;margin-bottom:5px;";
            toyHint.textContent = "Select a toy chip to target one toy, or leave on All.";
            toyPanel.appendChild(toyHint);
            // Toy selection chips (All + one per detected toy)
            let selectedToyGroup = null;
            const toyChipsRow = document.createElement("div");
            toyChipsRow.style.cssText = "display:flex;flex-wrap:wrap;gap:3px;min-height:18px;margin-bottom:5px;";
            toyPanel.appendChild(toyChipsRow);
            const toyGrid = document.createElement("div");
            toyGrid.style.cssText = "display:grid;grid-template-columns:repeat(5,1fr);gap:4px;";
            const toyStatus = document.createElement("div");
            toyStatus.style.cssText = "font-family:'Trebuchet MS',serif;font-size:11px;color:#79a885;min-height:13px;margin-top:2px;";
            const toyInfoEl = document.createElement("div");
            toyInfoEl.style.cssText = "font-family:'Trebuchet MS',serif;font-size:11px;color:#9a7080;min-height:13px;margin-top:3px;font-style:italic;";
            const refreshToyInfo = () => {
                const id = parseInt(qtSel.value, 10);
                if (!id) {
                    toyInfoEl.textContent = "";
                    return;
                }
                const toys = getTargetVibratingItems(id);
                if (toys.length === 0) {
                    toyInfoEl.textContent = "No toys detected.";
                    return;
                }
                if (selectedToyGroup) {
                    const t = toys.find(x => x.group === selectedToyGroup);
                    toyInfoEl.textContent = t ? `${t.name}: ${t.mode}` : "Toy not found.";
                }
                else {
                    toyInfoEl.textContent = toys.map(t => `${t.name}: ${t.mode}`).join("  ·  ");
                }
            };
            const refreshToyChips = () => {
                while (toyChipsRow.firstChild)
                    toyChipsRow.removeChild(toyChipsRow.firstChild);
                const id = parseInt(qtSel.value, 10);
                if (!id)
                    return;
                const toys = getTargetVibratingItems(id);
                if (toys.length === 0)
                    return;
                const mkChip = (label, grp) => {
                    const isSel = grp === selectedToyGroup;
                    const chip = document.createElement("button");
                    chip.style.cssText = `font-family:'Trebuchet MS',serif;font-size:10px;padding:2px 7px;border-radius:10px;border:1px solid ${isSel ? "#cf6f98" : "#5a3a50"};background:${isSel ? "#3a1028" : "#1a0d16"};color:${isSel ? "#cf6f98" : "#9a6878"};cursor:pointer;white-space:nowrap;`;
                    chip.textContent = label;
                    chip.addEventListener("click", () => { selectedToyGroup = grp; refreshToyChips(); refreshToyInfo(); });
                    toyChipsRow.appendChild(chip);
                };
                mkChip("All", null);
                for (const t of toys)
                    mkChip(t.name, t.group);
            };
            qtSel.addEventListener("change", () => { selectedToyGroup = null; refreshToyChips(); refreshToyInfo(); });
            toyHdr.addEventListener("click", () => { if (isToyOpen()) {
                selectedToyGroup = null;
                refreshToyChips();
                refreshToyInfo();
            } });
            for (const [, label, bg, bcMode] of TOY_MODES) {
                const btn = document.createElement("button");
                btn.style.cssText = `font-family:'Trebuchet MS',serif;font-size:11px;font-weight:bold;padding:7px 2px;border-radius:6px;border:1px solid #5a3a50;background:${bg};color:#cf6f98;cursor:pointer;transition:background 0.12s,border-color 0.12s;text-align:center;`;
                btn.textContent = label;
                btn.addEventListener("mouseenter", () => { btn.style.borderColor = "#cf6f98"; });
                btn.addEventListener("mouseleave", () => { btn.style.borderColor = "#5a3a50"; });
                btn.addEventListener("click", () => {
                    const id = parseInt(qtSel.value, 10);
                    if (!id) {
                        toyStatus.textContent = "Pick a Focus Target first.";
                        window.setTimeout(() => { toyStatus.textContent = ""; }, 2500);
                        return;
                    }
                    if (selectedToyGroup)
                        setTargetSingleToyMode(id, selectedToyGroup, bcMode);
                    else
                        setTargetToyMode(id, bcMode);
                    toyStatus.textContent = `✓ Set to ${label}.`;
                    window.setTimeout(() => { toyStatus.textContent = ""; refreshToyInfo(); refreshToyChips(); }, 1500);
                });
                toyGrid.appendChild(btn);
            }
            toyPanel.appendChild(toyGrid);
            toyPanel.appendChild(toyStatus);
            toyPanel.appendChild(toyInfoEl);
            refreshToyChips();
            refreshToyInfo();
            // ── ⛓ Curse ──────────────────────────────────────────────────────────
            const { panel: cursePanel, hdr: curseHdr, isOpen: isCurseOpen } = makeDomAccordion("⛓", "CURSE", actionsCard);
            const _cf = "font-family:'Trebuchet MS',serif;";
            // Hint text
            const curseHint = document.createElement("div");
            curseHint.style.cssText = `${_cf}font-size:10.5px;color:#7a5068;line-height:1.45;margin-bottom:8px;`;
            curseHint.textContent = "Target can't remove cursed items while EBC is loaded. Only you can lift the curse.";
            cursePanel.appendChild(curseHint);
            // ── Item picker card ────────────────────────────────────────────────
            const curseSelGroups = new Set();
            const curseCbs = [];
            const curseItemsCard = document.createElement("div");
            curseItemsCard.style.cssText = "background:rgba(10,4,14,0.9);border:1.5px solid #2a1022;border-radius:8px;overflow:hidden;margin-bottom:8px;";
            const curseItemsCardHdr = document.createElement("div");
            curseItemsCardHdr.style.cssText = `display:none;align-items:center;gap:7px;padding:5px 10px;background:rgba(35,12,26,0.7);border-bottom:1px solid #2a1022;`;
            const curseSelAllChk = document.createElement("input");
            curseSelAllChk.type = "checkbox";
            curseSelAllChk.style.cssText = "cursor:pointer;accent-color:#a03060;flex-shrink:0;";
            const curseItemsCardHdrLbl = document.createElement("span");
            curseItemsCardHdrLbl.style.cssText = `${_cf}font-size:10px;font-weight:bold;letter-spacing:0.1em;color:#5a3048;text-transform:uppercase;flex:1;`;
            curseItemsCardHdrLbl.textContent = "Items";
            const curseItemsCountLbl = document.createElement("span");
            curseItemsCountLbl.style.cssText = `${_cf}font-size:10px;color:#4a2038;`;
            curseItemsCountLbl.textContent = "";
            curseItemsCardHdr.appendChild(curseSelAllChk);
            curseItemsCardHdr.appendChild(curseItemsCardHdrLbl);
            curseItemsCardHdr.appendChild(curseItemsCountLbl);
            curseItemsCard.appendChild(curseItemsCardHdr);
            const curseItemsEl = document.createElement("div");
            curseItemsEl.style.cssText = "display:flex;flex-direction:column;max-height:150px;overflow-y:auto;";
            const curseItemsHint = document.createElement("div");
            curseItemsHint.style.cssText = `${_cf}font-size:11px;color:#4a2a38;padding:12px;text-align:center;`;
            curseItemsHint.textContent = "Select a Focus Target to see their items.";
            curseItemsEl.appendChild(curseItemsHint);
            curseItemsCard.appendChild(curseItemsEl);
            cursePanel.appendChild(curseItemsCard);
            const rebuildCurseItems = () => {
                while (curseItemsEl.firstChild)
                    curseItemsEl.removeChild(curseItemsEl.firstChild);
                curseSelGroups.clear();
                curseCbs.length = 0;
                curseSelAllChk.checked = false;
                curseSelAllChk.indeterminate = false;
                curseItemsCountLbl.textContent = "";
                const id = parseInt(qtSel.value, 10);
                if (!id) {
                    curseItemsCardHdr.style.display = "none";
                    curseItemsEl.appendChild(curseItemsHint);
                    return;
                }
                const items = getRoomMemberItems(id);
                if (items.length === 0) {
                    curseItemsCardHdr.style.display = "none";
                    const empty = document.createElement("div");
                    empty.style.cssText = `${_cf}font-size:11px;color:#4a2a38;padding:12px;text-align:center;`;
                    empty.textContent = "No items found (not in room?).";
                    curseItemsEl.appendChild(empty);
                    return;
                }
                curseItemsCardHdr.style.display = "flex";
                curseItemsCountLbl.textContent = `${items.length}`;
                for (const it of items) {
                    const row2 = document.createElement("div");
                    row2.style.cssText = "display:flex;align-items:center;gap:8px;padding:5px 10px;cursor:pointer;border-bottom:1px solid rgba(42,16,34,0.5);transition:background 0.1s;";
                    const chk = document.createElement("input");
                    chk.type = "checkbox";
                    chk.dataset.group = it.group;
                    chk.style.cssText = "cursor:pointer;flex-shrink:0;accent-color:#a03060;pointer-events:none;";
                    curseCbs.push(chk);
                    const nmWrap = document.createElement("div");
                    nmWrap.style.cssText = "flex:1;min-width:0;";
                    const nm2 = document.createElement("div");
                    nm2.style.cssText = `${_cf}font-size:11px;color:#c09ab0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;transition:color 0.1s;`;
                    nm2.textContent = it.craftName ? it.craftName : it.name;
                    const nmSub = document.createElement("div");
                    nmSub.style.cssText = `${_cf}font-size:9.5px;color:#5a3048;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-top:1px;`;
                    nmSub.textContent = it.craftName ? `${it.name} - ${it.group.replace("Item", "")}` : it.group.replace("Item", "");
                    nmWrap.appendChild(nm2);
                    nmWrap.appendChild(nmSub);
                    row2.appendChild(chk);
                    row2.appendChild(nmWrap);
                    if (it.locked) {
                        const lockIco2 = document.createElement("span");
                        lockIco2.style.cssText = "font-size:11px;flex-shrink:0;opacity:0.6;";
                        lockIco2.textContent = "🔒";
                        row2.appendChild(lockIco2);
                    }
                    const setRowSel = (sel) => {
                        row2.style.background = sel ? "rgba(140,40,80,0.18)" : "";
                        nm2.style.color = sel ? "#e8a0c0" : "#c09ab0";
                    };
                    row2.addEventListener("click", () => {
                        chk.checked = !chk.checked;
                        const g = chk.dataset.group;
                        if (g) {
                            if (chk.checked)
                                curseSelGroups.add(g);
                            else
                                curseSelGroups.delete(g);
                        }
                        setRowSel(chk.checked);
                        const n = curseCbs.filter(c => c.checked).length;
                        curseSelAllChk.indeterminate = n > 0 && n < curseCbs.length;
                        curseSelAllChk.checked = n === curseCbs.length;
                        curseItemsCountLbl.textContent = n > 0 ? `${n}/${items.length}` : `${items.length}`;
                    });
                    row2.addEventListener("mouseenter", () => { if (!chk.checked)
                        row2.style.background = "rgba(70,20,45,0.25)"; });
                    row2.addEventListener("mouseleave", () => { if (!chk.checked)
                        row2.style.background = ""; });
                    curseItemsEl.appendChild(row2);
                }
            };
            curseSelAllChk.addEventListener("change", () => {
                const sel = curseSelAllChk.checked;
                curseCbs.forEach(c => {
                    c.checked = sel;
                    const g = c.dataset.group;
                    if (g) {
                        if (sel)
                            curseSelGroups.add(g);
                        else
                            curseSelGroups.delete(g);
                    }
                    const row = c.parentElement;
                    if (row) {
                        row.style.background = sel ? "rgba(140,40,80,0.18)" : "";
                        const nmEl = row.querySelector("div > div:first-child");
                        if (nmEl)
                            nmEl.style.color = sel ? "#e8a0c0" : "#c09ab0";
                    }
                });
                curseSelAllChk.indeterminate = false;
                const total = curseCbs.length;
                curseItemsCountLbl.textContent = sel ? `${total}/${total}` : `${total}`;
            });
            qtSel.addEventListener("change", () => {
                if (isCurseOpen()) {
                    rebuildCurseItems();
                    rebuildActiveCurses();
                }
            });
            curseHdr.addEventListener("click", () => { if (isCurseOpen()) {
                rebuildCurseItems();
                rebuildActiveCurses();
            } });
            // ── Duration picker ─────────────────────────────────────────────────
            let curseDurMs = 0;
            const durSection = document.createElement("div");
            durSection.style.cssText = "margin-bottom:8px;";
            const durTopRow = document.createElement("div");
            durTopRow.style.cssText = "display:flex;align-items:center;gap:5px;margin-bottom:5px;";
            const durLbl = document.createElement("span");
            durLbl.style.cssText = `${_cf}font-size:10px;font-weight:bold;letter-spacing:0.1em;color:#5a3048;text-transform:uppercase;white-space:nowrap;`;
            durLbl.textContent = "Duration";
            durTopRow.appendChild(durLbl);
            const DUR_OPTS = [["Forever", 0], ["30m", 30 * 60000], ["1h", 3600000], ["2h", 7200000], ["4h", 14400000], ["8h", 28800000]];
